"use client";

import React, { useState, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Copy, Check, Users, Wallet, Clock, Share2, Gift } from "lucide-react";
import { cn } from "@/lib/utils";

// --- Types ---
type ReferralStatus = "active" | "inactive";

interface ReferralUser {
  id: number;
  name: string;
  date: string;
  status: ReferralStatus;
  timestamp: number;
}

// --- Sub-Components ---

const MetricCard = ({ label, value, icon, colorClass }: { label: string, value: string, icon: React.ReactNode, colorClass: string }) => (
  <div className="bg-background border border-border rounded-2xl p-5 flex items-center justify-between shadow-sm">
    <div className="flex items-center gap-4">
      <div className="p-2.5 bg-foreground/5 rounded-xl text-foreground-subtle">
        {icon}
      </div>
      <div>
        <p className="text-[7px] font-black uppercase tracking-[0.2em] opacity-40 mb-0.5">{label}</p>
        <h3 className={cn("text-lg font-black italic tracking-tighter", colorClass)}>{value}</h3>
      </div>
    </div>
  </div>
);

const UserCard = ({ user }: { user: ReferralUser }) => (
  <motion.div
    layout
    initial={{ opacity: 0, y: 10 }}
    animate={{ opacity: 1, y: 0 }}
    exit={{ opacity: 0, scale: 0.95 }}
    className="bg-background border border-border p-5 rounded-[1.5rem] flex flex-col justify-between h-32 shadow-sm"
  >
    <div className="flex justify-between items-start">
      <div className={cn("w-1.5 h-1.5 rounded-full", user.status === "active" ? "bg-emerald-500 shadow-[0_0_8px_emerald]" : "bg-orange-500")} />
      <span className={cn("text-[8px] font-black uppercase tracking-widest", user.status === "active" ? "text-emerald-500" : "text-orange-500")}>
        {user.status}
      </span>
    </div>

    <div>
      <h4 className="text-[11px] font-black italic uppercase tracking-tight truncate">{user.name}</h4>
      <div className="flex items-center justify-between mt-1">
        <span className="text-[7px] font-bold uppercase tracking-widest opacity-20">{user.date}</span>
        <span className={cn("text-xs font-black italic", user.status === "active" ? "text-foreground" : "opacity-10")}>
          ₹100
        </span>
      </div>
    </div>
  </motion.div>
);

// --- Main Page ---

export default function ReferralsPage() {
  const [copied, setCopied] = useState(false);
  const [filter, setFilter] = useState<"all" | ReferralStatus>("all");

  const referralCode = "FRIDAY-CAPTAIN-11";
  const referralLink = `https://fashionfriday.in/invite/${referralCode}`;

  // Mock Data
  const rawUsers: ReferralUser[] = [
    { id: 1, name: "Rahul S.", date: "22/01/26", status: "inactive", timestamp: 1737504000000 },
    { id: 2, name: "Sana K.", date: "24/01/26", status: "active", timestamp: 1737676800000 },
    { id: 3, name: "Kevin V.", date: "15/01/26", status: "active", timestamp: 1736899200000 },
    { id: 4, name: "Aditi R.", date: "25/01/26", status: "inactive", timestamp: 1737763200000 },
    { id: 5, name: "Mohammed A.", date: "18/01/26", status: "active", timestamp: 1737158400000 },
    { id: 6, name: "Priya M.", date: "10/01/26", status: "inactive", timestamp: 1736467200000 },
    { id: 7, name: "Daniel T.", date: "05/01/26", status: "inactive", timestamp: 1736035200000 },
    { id: 8, name: "Neha P.", date: "20/01/26", status: "active", timestamp: 1737331200000 },
    { id: 9, name: "Arjun D.", date: "12/01/26", status: "inactive", timestamp: 1736640000000 },
    { id: 15, name: "Zoya H.", date: "26/01/26", status: "active", timestamp: 1737849600000 },
  ];

  // Logic: Dynamic Metrics Calculation
  const stats = useMemo(() => {
    const activeCount = rawUsers.filter(u => u.status === "active").length;
    const inactiveCount = rawUsers.length - activeCount;
    return {
      activated: activeCount * 100,
      pending: inactiveCount * 100,
      total: rawUsers.length
    };
  }, [rawUsers]);

  const sortedUsers = useMemo(() => {
    return rawUsers
      .filter(u => filter === "all" || u.status === filter)
      .sort((a, b) => b.timestamp - a.timestamp); // Latest on top
  }, [filter]);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: "Fashion Friday",
          text: "Join me on Fashion Friday! Style that moves. Get ₹100 reward!",
          url: referralLink,
        });
      } catch (err) { console.log("Share failed", err); }
    } else { handleCopy(referralLink); }
  };

  return (
    <div className="min-h-screen bg-[#F9F9F9] dark:bg-black text-foreground px-4 md:px-8 py-10 transition-colors duration-500">
      <main className="mx-auto max-w-4xl space-y-6 md:pt-12">
        
        {/* HERO SECTION */}
        <section className="relative p-8 rounded-tr-[4rem] rounded-bl-[4rem] rounded-xl overflow-hidden min-h-[220px] flex items-center shadow-2xl">
          <div 
            className="absolute inset-0 bg-cover bg-center transition-transform duration-700 hover:scale-105" 
            style={{ backgroundImage: "url('/images/refferal/hero.png')" }} 
          />
          <div className="absolute inset-0 bg-black/60 backdrop-blur-[2px]" />

          <div className="relative z-10 w-full space-y-6">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-white/10 rounded-2xl backdrop-blur-md">
                <Gift size={24} className="text-white" />
              </div>
              <h2 className="text-2xl font-black italic uppercase tracking-tighter text-white">
                Share the Vibe. <span className="text-emerald-400">Earn Credits.</span>
              </h2>
            </div>

            <div className="flex flex-col lg:flex-row gap-3">
              <div className="flex items-center bg-black/40 border border-white/20 rounded-xl px-4 py-3 flex-1 backdrop-blur-md">
                <code className="text-xs font-black uppercase tracking-widest text-white/90 truncate">{referralCode}</code>
                <button onClick={() => handleCopy(referralCode)} className="ml-auto text-white/60 hover:text-white flex items-center gap-2">
                   {copied ? <><Check size={14} className="text-emerald-400" /><span className="text-[10px] font-bold">COPIED</span></> : <><Copy size={14} /><span className="text-[10px] font-bold">COPY</span></>}
                </button>
              </div>
              <button onClick={handleShare} className="bg-white text-black h-12 px-10 rounded-xl font-black uppercase text-[11px] tracking-widest flex items-center justify-center gap-2 hover:bg-emerald-400 transition-all">
                <Share2 size={16} /> SHARE INVITE
              </button>
            </div>
          </div>
        </section>

        {/* METRICS GRID */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <MetricCard label="Activated Balance" value={`₹${stats.activated}`} icon={<Wallet size={16} />} colorClass="text-emerald-500" />
          <MetricCard label="Pending Approval" value={`₹${stats.pending}`} icon={<Clock size={16} />} colorClass="text-orange-500" />
          <MetricCard label="Network Size" value={`${stats.total} Users`} icon={<Users size={16} />} colorClass="text-foreground" />
        </div>

        {/* ACTIVITY SECTION */}
        <div className="space-y-4 pt-6">
          <div className="flex items-center justify-between px-2">
            <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-foreground-subtle">Referral Activity</h3>
            
            <div className="flex items-center gap-1 bg-foreground/5 p-1 rounded-xl border border-border">
              {(["all", "active", "inactive"] as const).map((s) => (
                <button
                  key={s}
                  onClick={() => setFilter(s)}
                  className={cn(
                    "px-5 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all",
                    filter === s ? "bg-background text-foreground shadow-sm" : "opacity-30 hover:opacity-100"
                  )}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 pb-12">
            <AnimatePresence mode="popLayout">
              {sortedUsers.map((user) => (
                <UserCard key={user.id} user={user} />
              ))}
            </AnimatePresence>
          </div>

          {sortedUsers.length === 0 && (
            <div className="py-20 text-center border-2 border-dashed border-border rounded-[2rem] opacity-30">
               <p className="text-[10px] font-black uppercase tracking-widest italic">No activity found under "{filter}"</p>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}